							node_ids: [0, 4],
							data: [null,{type:"data",data:{posts:[{slug:"iristick-announces-major-capital-increase",title:"Iristick announces major capital increase enabling accelerated user adoption",intro:"Iristick’s smart glasses are being used by professionals across industries in Europe and the US since the company was founded in 2015. Various large-scale proof-of-concept projects are underway, which are expected to lead to accelerated adoption of smart glasses in 2023-2024.",image:"/_app/immutable/assets/Thumbnail%20Capital%20Increase.2rlvHSb6.webp",date:"22 February 2023"},{slug:"tackle-business-travel-emissions",title:"How to tackle business travel emissions and reduce your carbon footprint",intro:"A warming climatic system is expected to impact the availability of necessities like freshwater, food security, and energy, while efforts to redress climate change, both through adaptation and mitigation, will inform and shape the global development agenda in the coming years.",image:"/_app/immutable/assets/Iristick%20H1%20smart%20glasses_field%20service%20workerThumb._AFrnfty.webp",date:"26 October 2022"},{slug:"also-and-iristick-smart-glasses-extend-partnership",title:"Also and Iristick extend partnership",intro:"ALSO announces their collaboration with Iristick, one of the world’s leading providers of assisted reality solutions for frontline industrial workers. The company’s wearable solutions will be provided to B2B customers across BeNeLux, DACH and the Nordic region.",image:"/_app/immutable/assets/ALSO_partnershipThumb.DCPaJkML.webp",date:"11 October 2022"},{slug:"webinar-handtmann-icona",title:"Join our webinar co-hosted with Handtmann and Icona",intro:"Join us for a webinar on Wednesday, 21 September, co-hosted by Iristick, Handtmann and Icona. We will demonstrate how smart glasses technology, paired with the right software, can elevate efficiency and decrease costs in your business. Register now to find out how our solution can enable faster and more efficient trainings, and help mitigate the effects of the labour shortage in the manufacturing industry.",image:"/_app/immutable/assets/Handtmann_Acty_WebinarThumb.C0MTOG7V.webp",date:"6 September 2022"},{slug:"second-generation-smart-glasses-iristick",title:"Second Generation Smart Glasses - What Makes Them Future Proof",intro:"In the beginning of the month, Qualcomm’s Hugo Swart gave a comprehensive overview of the evolution of smart glasses in his keynote speech at the AWE USA event. He explained that as these devices evolve, they are going to start connecting to phones to leverage their processing power. But what does this mean exactly and why is it an advantage for smart glasses to connect to a phone? In this article, we will take a deep dive into these so-called phone-tethered devices and the benefits they offer.",image:"/_app/immutable/assets/Iristick%20G2%20smart%20glasses_with%20iOS%20iPhone11Thumb.C-8Q52CD.webp",date:"20 July 2022"},{slug:"challenges-of-field-service-operations-during-summer-holidays-and-how-to-tackle-them",title:"Challenges of Field Service Operations During Summer Holidays and How To Tackle Them",intro:"Summer has arrived. It is a season when schools are closed, and most people take vacations. However, we all keep on working except for our holidays, like the rest of the year. It can be challenging to people on the northern hemisphere since it can mean high temperatures and longer days.",image:"/_app/immutable/assets/Challenges%20Field%20Service%20Operations%20SummerThumb.Cot9GQH2.webp",date:"12 July 2022"},{slug:"agrifood-professionals-benefit-from-smartglasses",title:"Four Ways Agri-Food Professionals Can Benefit from Smart Glasses",intro:"Global food production system is facing tremendous challenges. Agricultural productivity needs to increase significantly to feed a growing global population, while its environmental footprint must decrease to help mitigate climate change. In addition, millions of farmers worldwide, work long hours to provide us with nutritious food and operate in tough socio-economic environments. Hence the productivity and environmental challenges must be tackled in a way that also allows farmers to make a decent living.",image:"/_app/immutable/assets/Benefits%20for%20Agri-Food%20ProfessionalsThumb.CC09W5SK.webp",date:"5 July 2022"},{slug:"webinar-hands-free-microsoft-teams-iristick",title:"WEBINAR: Hands-free Microstoft Teams meeting with voice commands on Iristick smart glasses",intro:"Join us for a deep dive into the benefits that hands-free Microsoft Teams video conferencing on Iristick smart glasses can offer to your business. Hosted by Iristick and Microsoft, this webinar includes an introduction to ‘Microsoft Teams on Iristick’, a video conferencing solution fully optimized for voice commands to enable hands-free remote assistance to deskless employees in any environment. The webinar will end with a Q&A session where experts from Iristick and Microsoft will respond to your questions.",image:"/_app/immutable/assets/Webinar-28-June-Microsoft-Teams-on-Iristick-Smart-GlassesThumb%20.CyhZyGeD.webp",date:"9 June 2022"},{slug:"join-webinar-hands-free-remote-assistance-smart-glasses-hazardous-areas",title:"WEBINAR: Hands-free Remote Assistance - Smart Glasses and RemoteEye in Hazardous Areas",intro:"Join Iristick, Pepperl+Fuchs and Wideum for a deep dive into how you can implement hands-free remote assistance and increase your efficiencies in operations and reduce downtime.",image:"/_app/immutable/assets/Webinar%20Remote%20Assistance%20Hazardous%20AreasThumb.3MLr9aP_.webp",date:"11 May 2022"},{slug:"microsoft-teams-on-iristick-available-on-smart-glasses",title:"Iristick launches ‘Microsoft Teams on Iristick’ that enables multifunctional video conferencing on its smart glasses",intro:"ANTWERP, 4 MAY 2022 - Iristick, leading supplier of industrial and medical smart glasses announced today the launch of Microsoft Teams video conferencing solution on their products. Fully optimized for use with voice commands, ‘Microsoft Teams on Iristick’ provides a completely hands-free option for remote assistance and collaboration.",image:"/_app/immutable/assets/Microsoft-Teams-on-Iristick-video-conferencingThumb.Ba-pDJBU.webp",date:"4 May 2022"},{slug:"iristick-distribution-agreement-capestone",title:"Iristick Signs Distribution Agreement With Capestone",intro:"Iristick announced today the signature of a distribution agreement for industrial smart glasses with Capestone, distributor of high-technology Wireless Wan & IoT solutions. Iristick smart glasses feature live streaming technology, enabling “hands-free” remote assistance, work instruction guidance and pick-by-vision. Unique to the Iristick smart glasses is the use of the processing power of a smartphone, significantly reducing implementation costs. For Capestone an important reason to further strengthen the distribution and footprint of Iristick in Europe by this complementary offering to the current smart glass portfolio.",image:"/_app/immutable/assets/Partnership-Capestone-IristickThumb.Dg817omU.webp",date:"19 april 2022"},{slug:"vr-ar-xr-difference",title:"vr-ar-xr-difference",intro:"VR, AR, aR, XR - the media has been flooded with these terms in the past few years. Though we come across them every day, some of us may find it difficult to fully understand what they stand for. However, there is a good reason why these technologies are among the most trending topics: they are all undeniable parts of our future. No matter the sector or industry, we can be certain that these new “realities” will be present in one way or another, making our work more efficient, and our lives more convenient. In this article, we'll briefly explain what each of these technologies are and what they are used for.",image:"/_app/immutable/assets/Banner-for-aR-VR-XR-AR-smart-glasses-articleThumb.reDXfMKm.webp",date:"11 April 2022"}]},uses:{}}],
